args:
set -e
install -d -o postgres -g postgres /tmp/pireus-qa
gosu postgres initdb -D /tmp/pireus-qa/data --auth-local=trust --auth-host=reject > /tmp/init.log
gosu postgres pg_ctl -D /tmp/pireus-qa/data -l /tmp/pireus-qa/postgres.log -o "-c listen_addresses='' -c shared_preload_libraries=pg_search,pg_cron,pg_stat_statements -c cron.launch_active_jobs=off" -w start
trap 'gosu postgres pg_ctl -D /tmp/pireus-qa/data -m fast -w stop' EXIT
gosu postgres psql -X -v ON_ERROR_STOP=1 -d postgres -c 'CREATE EXTENSION pg_cron'
gosu postgres createdb probe
gosu postgres psql -X -v ON_ERROR_STOP=1 -d probe <<'SQL'
CREATE EXTENSION pg_search;
CREATE EXTENSION vector;
CREATE EXTENSION pg_ivm;
CREATE EXTENSION postgis;
CREATE EXTENSION postgis_topology;
CREATE EXTENSION fuzzystrmatch;
CREATE EXTENSION postgis_tiger_geocoder;
CREATE EXTENSION pg_stat_statements;
CREATE TABLE public.probe_docs(id integer PRIMARY KEY, body text, v vector(3));
INSERT INTO public.probe_docs VALUES (1,'pireus ontology','[1,2,3]'), (2,'unrelated sample','[1,2,4]');
CREATE INDEX probe_bm25 ON public.probe_docs USING bm25(id,body) WITH(key_field='id');
CREATE TABLE public.probe_base(id integer PRIMARY KEY);
SELECT pgivm.create_immv('public.probe_immv','SELECT count(*) AS n FROM public.probe_base');
INSERT INTO public.probe_base VALUES(1),(2);
DO $check$
BEGIN
 IF (SELECT count(*) FROM public.probe_docs WHERE body @@@ 'pireus') <> 1 THEN RAISE EXCEPTION 'BM25 mismatch'; END IF;
 IF ('[1,2,3]'::vector <-> '[1,2,4]'::vector) <> 1 THEN RAISE EXCEPTION 'vector mismatch'; END IF;
 IF ST_Distance(ST_Point(0,0),ST_Point(3,4)) <> 5 THEN RAISE EXCEPTION 'PostGIS mismatch'; END IF;
 IF (SELECT n FROM public.probe_immv) <> 2 THEN RAISE EXCEPTION 'IVM mismatch'; END IF;
END $check$;
SELECT 'FUNCTIONAL_EXTENSIONS_PASS';
SQL
gosu postgres pg_dump -Fc -d probe -f /tmp/pireus-qa/probe.dump
gosu postgres createdb replay
gosu postgres pg_restore --exit-on-error -d replay /tmp/pireus-qa/probe.dump
gosu postgres psql -X -v ON_ERROR_STOP=1 -d replay <<'SQL'
INSERT INTO public.probe_base VALUES (3);
DO $check$ BEGIN
 IF (SELECT n FROM public.probe_immv) <> 3 THEN RAISE EXCEPTION 'Restored IVM no longer maintains itself'; END IF;
 IF (SELECT count(*) FROM public.probe_docs WHERE body @@@ 'pireus') <> 1 THEN RAISE EXCEPTION 'Restored BM25 mismatch'; END IF;
END $check$;
SELECT 'SYNTHETIC_RESTORE_PASS';
SQL
